function RenderAgentsPanel({ main, head, agents, emptyText }) {
  if (agents.length === 0) {
    DestroyActiveChat();
    main.innerHTML = `${head}<p class="dash-empty">${EscapeHtml(emptyText)}</p>`;
    return;
  }
  const selKey = state.contentCache.selectedAgentKey;
  const log = state.contentCache.agentLog;
